Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "PaymentOrder",
   "table": "payment_orders",
   "legacy_table": "ORDENES",
   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ORD_NUMERO"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ORD_EMPRESA"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ORD_ESTADO"
    },
    {
     "name": "value",
     "type": "decimal(11,2,signed)",
     "column": "value",
     "legacy": "ORD_VALOR"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": "movement_number",
     "legacy": "ORD_MOVIM"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": "commission",
     "legacy": "ORD_COMIS"
    }
   ]
  },
  {
   "name": "Account",
   "table": "accounts",
   "legacy_table": "CUENTAS",
   "key": [
    "accountNumber"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": "account_number",
     "legacy": "CTA_NUMERO"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "CTA_TIPO"
    },
    {
     "name": "balance",
     "type": "decimal(13,2,signed)",
     "column": "balance",
     "legacy": "CTA_SALDO"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "CTA_ESTADO"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "OrderRepository",
   "entity": "PaymentOrder",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByKey",
     "description": "Reads the order by order number and company. Empty when it does not exist.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      }
     ],
     "returns": "PaymentOrder",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Sets the order to paid ('G') and stores the movement number and the commission charged.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      },
      {
       "name": "movementNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "ORD_MOVIM"
      },
      {
       "name": "commission",
       "type": "decimal(5,2,signed)",
       "column": null,
       "legacy": "ORD_COMIS"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumber",
     "description": "Reads the account by number. Empty when it does not exist.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    },
    {
     "name": "updateBalance",
     "description": "Rewrites the balance of the account after a debit.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      },
      {
       "name": "balance",
       "type": "decimal(13,2,signed)",
       "column": null,
       "legacy": "CTA_SALDO"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "MovementGateway",
   "entity": null,
   "legacy_program": "PAGOMOV",
   "methods": [
    {
     "name": "registerMovement",
     "description": "Registers the movement of the payment and returns its movement number.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "MOV_ORDEN"
      }
     ],
     "returns": "long",
     "legacy_output": "MOV_NUMERO"
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "PayOrder",
   "description": "Validates the payment request, reads the pending order, checks the amount, calculates the commission, debits the customer account (rules of PAGODEB), registers the movement through PAGOMOV and marks the order as paid, in one transaction.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013",
    "RULE-014",
    "RULE-015"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "ORDEN"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "EMPRESA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "TIPCTA"
    },
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "CUENTA"
    },
    {
     "name": "amount",
     "type": "decimal(11,2,signed)",
     "column": null,
     "legacy": "VALOR"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "CANAL"
    },
    {
     "name": "approvalKey",
     "type": "text(fixed,6,iso8859-1)",
     "column": null,
     "legacy": "CLAVE"
    }
   ],
   "outputs": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "RORDEN"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": null,
     "legacy": "RCOMIS"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "RMOVIM"
    },
    {
     "name": "message",
     "type": "text(var,40,iso8859-1)",
     "column": null,
     "legacy": "RMENS"
    }
   ],
   "errors": [
    {
     "code": "INVALID_ORDER_NUMBER",
     "legacy_code": "-1",
     "message": "NUMERO DE ORDEN INVALIDO"
    },
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "-1",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "CHANNEL_NOT_ALLOWED",
     "legacy_code": "-1",
     "message": "CANAL NO PERMITIDO"
    },
    {
     "code": "APPROVAL_KEY_REQUIRED",
     "legacy_code": "-1",
     "message": "CLAVE DE APROBACION REQUERIDA"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "-1",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "-1",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "AMOUNT_MISMATCH",
     "legacy_code": "-1",
     "message": "VALOR NO COINCIDE CON LA ORDEN"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "-1",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "-1",
     "message": "SALDO INSUFICIENTE"
    },
    {
     "code": "INVALID_ACCOUNT",
     "legacy_code": "-1",
     "message": "CUENTA NO VALIDA"
    }
   ],
   "ports": [
    "OrderRepository",
    "AccountRepository",
    "MovementGateway"
   ],
   "http_method": "POST",
   "path": "/payments/orders/pay",
   "legacy_program": "PAGOORD",
   "unit_of_work": {
    "begins_at": 37,
    "commits_at": 172,
    "savepoints": [],
    "rollbacks": []
   },
   "legacy_message": "MENSAJE"
  },
  {
   "name": "SelectMenuOption",
   "description": "Routes the option chosen on the payments main menu: 1 goes to order payment, 9 ends the session, anything else is rejected.",
   "rules": [
    "RULE-006"
   ],
   "inputs": [
    {
     "name": "option",
     "type": "text(fixed,1,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    }
   ],
   "outputs": [
    {
     "name": "destination",
     "type": "text(var,8,iso8859-1)",
     "column": null,
     "legacy": "PROGRAM"
    },
    {
     "name": "message",
     "type": "text(var,78,iso8859-1)",
     "column": null,
     "legacy": "MENSAJEO"
    }
   ],
   "errors": [
    {
     "code": "INVALID_OPTION",
     "legacy_code": "OPCION_NO_VALIDA",
     "message": "OPCION NO VALIDA"
    }
   ],
   "ports": [],
   "http_method": "POST",
   "path": "/payments/menu/option",
   "legacy_program": "PAGOMNU",
   "unit_of_work": null,
   "legacy_message": "MENSAJEO"
  }
 ],
 "decisions": [
  {
   "title": "Data moves to the target database",
   "context": "The legacy keeps ORDENES and CUENTAS in VSAM KSDS files accessed with CICS READ/REWRITE.",
   "decision": "data_strategy is migration: ORDENES becomes payment_orders and CUENTAS becomes accounts, with the legacy precision (9(7), 9(5), S9(9)V99, S9(11)V99, S9(3)V99).",
   "consequences": "The service reads and writes relational tables. The golden master traces load the legacy table contents into these tables."
  },
  {
   "title": "PAGODEB is folded into the PayOrder use case",
   "context": "PAGOORD calls PAGODEB with LINK to debit the account, and both work on the same unit of work. The source of PAGODEB is available and its data moves.",
   "decision": "The rules of PAGODEB (RULE-001 to RULE-005) are implemented inside PayOrder through AccountRepository, in the same order as the legacy (not found, type mismatch, inactive, balance below amount, debit). DEB-RESP '30' and '40' end as INVALID_ACCOUNT, '10' as ACCOUNT_INACTIVE and '20' as INSUFFICIENT_FUNDS, as PAGOORD does.",
   "consequences": "There is no DebitGateway port. A balance equal to the amount is allowed, as in the legacy."
  },
  {
   "title": "One transaction replaces the CICS syncpoint",
   "context": "PAGOORD rewrites the account (PAGODEB) and the order, and commits with SYNCPOINT at line 172. There is no rollback point in the legacy: every rejection happens before the first write.",
   "decision": "PayOrder runs in one transaction that begins at line 37 and commits at line 172. No savepoints and no rollbacks are declared.",
   "consequences": "If a technical failure happens after the debit (e.g. the movement registration fails) the whole transaction is undone, which the CICS task would do on abend."
  },
  {
   "title": "Rejections are business errors",
   "context": "The traces show that every rejection returns status -1 with only the message (MENSAJE) and leaves the tables unchanged.",
   "decision": "Each rejection is a business error with a stable code and the legacy message. legacy_code is -1 for all of them and legacy_message is MENSAJE.",
   "consequences": "The HTTP layer maps each error code to a 4xx response with the message. The screen message 'TECLA NO VALIDA' and the map handling are not translated."
  },
  {
   "title": "Amount is received as a decimal",
   "context": "The screen field VALORI is a digit string converted with NUMVAL/100 (implied decimals). The traces provide VALOR as a decimal amount ('1500.00') that is compared with ORD_VALOR.",
   "decision": "The service receives amount as decimal(11,2,signed) and compares it with the order value exactly (scale 2). The conversion of the screen digits is a concern of the client.",
   "consequences": "RULE-012 is kept as an equality check between the typed amount and the order value."
  },
  {
   "title": "Commission rule kept as constants of the domain",
   "context": "RULE-013: 50,000 or more pays 0, WEB pays 1.00 and any other channel pays 2.50; the total debited is value plus commission.",
   "decision": "The calculation is done in the use case with decimal arithmetic at scale 2; it is not stored in a table.",
   "consequences": "A change of tariff requires a code change."
  },
  {
   "title": "Pseudo-conversational state and screens are not translated",
   "context": "PAGOORD and PAGOMNU use maps, EIBAID, a 13-byte commarea (CA-ULTIMA-ORDEN) and XCTL/RETURN TRANSID.",
   "decision": "The services are stateless HTTP endpoints. The menu use case only returns the destination (PAGOORD, END) and the message; the commarea and the PF3/ENTER handling belong to the client.",
   "consequences": "CA-ULTIMA-ORDEN is not stored in the target. Option 9 returns destination END with the message 'SESION TERMINADA'."
  },
  {
   "title": "PAGOMOV is an external program behind a port",
   "context": "PAGOMOV is not in the inputs and is stubbed in the traces; PAGOORD does not check its return status and uses only MOV_NUMERO.",
   "decision": "MovementGateway.registerMovement calls PAGOMOV with MOV_ORDEN and returns MOV_NUMERO. Its return status is not mapped.",
   "consequences": "The traces replay PAGOMOV with its recorded stub."
  }
 ],
 "masks": [],
 "infrastructure": [],
 "data_strategy": "migration"
}

Use case: PayOrder

Rules:
[
 {
  "id": "RULE-001",
  "name": "Debit rejected when account does not exist",
  "category": "validation",
  "priority": "P0",
  "statement": "A debit against an account number that is not on the CUENTAS file is rejected with response code '30' and the balance is not changed.",
  "condition": "READ of CUENTAS by DEB-CUENTA returns NOTFND",
  "action": "Set DEB-RESP = '30'; no debit is made.",
  "inputs": [
   {
    "name": "DEB-CUENTA",
    "type": "decimal(10,0,unsigned)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account not found\n Given no account 9999999999 exists in CUENTAS\n When a debit of 100.00 is requested for account 9999999999\n Then DEB-RESP is '30'\n And no balance is changed"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 18,
    "line_end": 23
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Debit rejected when account type differs from requested type",
  "category": "validation",
  "priority": "P0",
  "statement": "When the account type stored on the account (CTA-TIPO) is not equal to the type requested in the debit (DEB-TIPO), DEB-RESP is set to '40'.",
  "condition": "Account found AND CTA-TIPO <> DEB-TIPO",
  "action": "Set DEB-RESP = '40'; no debit is made.",
  "inputs": [
   {
    "name": "CTA-TIPO",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   },
   {
    "name": "DEB-TIPO",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Type mismatch\n Given account 1234567890 exists with CTA-TIPO 'AHO'\n When a debit of 50.00 is requested with DEB-TIPO 'COR'\n Then DEB-RESP is '40'\n And the balance is unchanged"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 24,
    "line_end": 25
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Debit rejected when account is not active",
  "category": "validation",
  "priority": "P0",
  "statement": "When the account is not active (NOT CTA-ACTIVA), DEB-RESP is set to '10'.",
  "condition": "Account found AND CTA-TIPO = DEB-TIPO AND NOT CTA-ACTIVA",
  "action": "Set DEB-RESP = '10'; no debit is made.",
  "inputs": [
   {
    "name": "CTA-ESTADO",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Inactive account\n Given account 1234567890 exists, the type matches, and the account is not active\n When a debit of 50.00 is requested\n Then DEB-RESP is '10'\n And the balance is unchanged"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 26,
    "line_end": 27
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Debit rejected for insufficient funds",
  "category": "validation",
  "priority": "P0",
  "statement": "When CTA-SALDO is strictly less than DEB-MONTO, the debit is rejected by setting DEB-RESP to '20'. A debit equal to the balance is not rejected by this check.",
  "condition": "Account found, type matches, account active AND CTA-SALDO < DEB-MONTO",
  "action": "Set DEB-RESP = '20'; no debit is made.",
  "inputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-MONTO",
    "type": "decimal(13,2,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Insufficient balance\n Given an active account with CTA-SALDO 100.00 and a matching type\n When a debit of 100.01 is requested\n Then DEB-RESP is '20'\n And the balance stays 100.00",
   "Scenario: Balance equal to amount is allowed\n Given an active account with CTA-SALDO 100.00 and a matching type\n When a debit of 100.00 is requested\n Then the debit proceeds"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 28,
    "line_end": 29
   }
  ]
 },
 {
  "id": "RULE-005",
  "name": "Successful debit reduces balance",
  "category": "calculation",
  "priority": "P0",
  "statement": "When none of the preceding WHEN branches of the evaluation apply (WHEN OTHER), the debit amount DEB-MONTO is subtracted from CTA-SALDO, the CUENTAS record is rewritten from CTA-REGISTRO, and DEB-RESP is set to '00'.",
  "condition": "None of the rejection conditions ('30','40','10','20') apply",
  "action": "CTA-SALDO = CTA-SALDO - DEB-MONTO; REWRITE the CUENTAS record; DEB-RESP = '00'.",
  "inputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-MONTO",
    "type": "decimal(13,2,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Successful debit\n Given an active account with CTA-SALDO 500.00 and a matching type\n When a debit of 120.50 is requested\n Then CTA-SALDO becomes 379.50\n And DEB-RESP is '00'"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 30,
    "line_end": 31
   },
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 35,
    "line_end": 39
   }
  ]
 },
 {
  "id": "RULE-007",
  "name": "Order number must be numeric and non-zero",
  "category": "validation",
  "priority": "P1",
  "statement": "When the order number ORDENI is not numeric or equals zeros, the message 'NUMERO DE ORDEN INVALIDO' is set in WS-MENSAJE and the HAY-ERROR flag is set.",
  "condition": "ORDENI NOT NUMERIC OR ORDENI = ZEROS",
  "action": "Set message 'NUMERO DE ORDEN INVALIDO' and flag the request as in error. No order is read and no debit is made.",
  "inputs": [
   {
    "name": "ORDENI",
    "type": "text(fixed,7,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order number is zero\n Given the order number entered is 0000000\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown and the payment is not processed",
   "Scenario: Order number contains letters\n Given the order number entered is 12A4567\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 83,
    "line_end": 85
   }
  ]
 },
 {
  "id": "RULE-008",
  "name": "Allowed account types for order payment",
  "category": "validation",
  "priority": "P0",
  "statement": "Only account types CTE, AHO and VIR may be used to pay an order. Any other type is rejected with 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "TIPCTAI NOT IN ('CTE','AHO','VIR')",
  "action": "Set message 'TIPO DE CUENTA NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "TIPCTAI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Savings account accepted\n Given a valid order number and account type AHO\n When the request is validated\n Then the account type check passes",
   "Scenario: Unknown account type\n Given a valid order number and account type XYZ\n When the request is validated\n Then the message 'TIPO DE CUENTA NO PERMITIDO' is shown"
  ],
