import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class PayOrderServiceTest {

    // The copybooks ORDREG / CTAREG are not available: the code of ORD-PENDIENTE and of CTA-ACTIVA
    // are UNRESOLVED_DEPENDENCY. 'P' and 'A' are used as pending / active, any other value as
    // not pending / not active. 'G' (paid) is evidenced by the source of the port.
    private static final String PENDING = "P";
    private static final String PAID = "G";
    private static final String ACTIVE = "A";
    private static final String INACTIVE = "I";

    private static final int COMPANY = 10;
    private static final long ACCOUNT = 1234567890L;
    private static final long MOVEMENT = 9000000001L;

    /** In-memory fakes of the three ports, recording every call in order. */
    private static final class Harness {
        final List<String> events = new ArrayList<>();
        PaymentOrder order;
        Account account;
        long movementToReturn = MOVEMENT;

        final OrderRepository orders = new OrderRepository() {
            @Override
            public Optional<PaymentOrder> findByKey(Integer orderNumber, Integer companyId) {
                events.add("findOrder:" + orderNumber + ":" + companyId);
                return Optional.ofNullable(order);
            }

            @Override
            public int markPaid(Integer orderNumber, Integer companyId, Long movementNumber, BigDecimal commission) {
                events.add("markPaid:" + orderNumber + ":" + companyId + ":" + movementNumber + ":"
                        + commission.setScale(2).toPlainString());
                return 1;
            }
        };

        final AccountRepository accounts = new AccountRepository() {
            @Override
            public Optional<Account> findByNumber(Long accountNumber) {
                events.add("findAccount:" + accountNumber);
                return Optional.ofNullable(account);
            }

            @Override
            public int updateBalance(Long accountNumber, BigDecimal balance) {
                events.add("updateBalance:" + accountNumber + ":" + balance.setScale(2).toPlainString());
                return 1;
            }
        };

        final MovementGateway movements = orderNumber -> {
            events.add("registerMovement:" + orderNumber);
            return movementToReturn;
        };

        PayOrderService service() {
            return new PayOrderService(orders, accounts, movements);
        }

        Harness withOrder(String status, String value) {
            order = new PaymentOrder(1234567, COMPANY, status, new BigDecimal(value), null, null);
            return this;
        }

        Harness withAccount(String type, String balance, String status) {
            account = new Account(ACCOUNT, type, new BigDecimal(balance), status);
            return this;
        }

        boolean anyWrite() {
            return events.stream().anyMatch(e -> e.startsWith("updateBalance") || e.startsWith("registerMovement")
                    || e.startsWith("markPaid"));
        }
    }

    private static PayOrderRequest req(String orderNumber, String accountType, String amount, String channel,
            String key) {
        return new PayOrderRequest(orderNumber, COMPANY, accountType, ACCOUNT, new BigDecimal(amount), channel, key);
    }

    private static PayOrderRequest okWeb(String amount) {
        return req("1234567", "CTE", amount, "WEB", "      ");
    }

    private static void assertRejected(Harness h, PayOrderRequest r, String code, String message) {
        assertThatThrownBy(() -> h.service().execute(r))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError be = (BusinessError) e;
                    assertThat(be.code()).isEqualTo(code);
                    assertThat(be.legacyCode()).isEqualTo("-1");
                    assertThat(be.getMessage()).isEqualTo(message);
                });
        assertThat(h.anyWrite()).isFalse();
    }

