        // total = 1000.00 + 1.00 = 1001.00 ; 5000.00 - 1001.00 = 3999.00
        Harness h = new Harness().withOrder(PENDING, "1000.00").withAccount("CTE", "5000.00", ACTIVE);
        h.service().execute(okWeb("1000.00"));
        assertThat(h.events).contains("updateBalance:1234567890:3999.00");
    }

    @Test
    void rule_005_successful_debit_keeps_cents() {
        // total = 120.50 + 1.00 = 121.50 ; 500.00 - 121.50 = 378.50
        Harness h = new Harness().withOrder(PENDING, "120.50").withAccount("CTE", "500.00", ACTIVE);
        h.service().execute(okWeb("120.50"));
        assertThat(h.events).contains("updateBalance:1234567890:378.50");
    }

    @Test
    void rule_015_successful_payment_registers_movement_marks_order_paid_and_answers() {
        Harness h = new Harness().withOrder(PENDING, "1000.00").withAccount("CTE", "5000.00", ACTIVE);
        PayOrderResponse r = h.service().execute(okWeb("1000.00"));

        assertThat(r.orderNumber()).isEqualTo(1234567);
        assertThat(r.commission()).isEqualByComparingTo(new BigDecimal("1.00"));
        assertThat(r.movementNumber()).isEqualTo(9000000001L);
        assertThat(r.message()).isEqualTo("PAGO REALIZADO");

        assertThat(h.events).containsExactly(
                "findOrder:1234567:10",
                "findAccount:1234567890",
                "updateBalance:1234567890:3999.00",
                "registerMovement:1234567",
                "markPaid:1234567:10:9000000001:1.00");
    }

    @Test
    void rule_015_movement_number_returned_by_the_gateway_is_the_one_stored_and_answered() {
        Harness h = new Harness().withOrder(PENDING, "1000.00").withAccount("CTE", "5000.00", ACTIVE);
        h.movementToReturn = 4294967296L;
        PayOrderResponse r = h.service().execute(req("1234567", "CTE", "1000.00", "OFI", "ABC123"));
        assertThat(r.movementNumber()).isEqualTo(4294967296L);
        assertThat(h.events).contains("markPaid:1234567:10:4294967296:2.50");
    }

    @Test
    void rule_015_no_write_happens_when_the_debit_is_rejected() {
        Harness h = new Harness().withOrder(PENDING, "1000.00").withAccount("CTE", "10.00", ACTIVE);
        assertRejected(h, okWeb("1000.00"), "INSUFFICIENT_FUNDS", "SALDO INSUFICIENTE");
        assertThat(h.events).noneMatch(e -> e.startsWith("registerMovement") || e.startsWith("markPaid"));
    }
